/* Narrow viewports: the row scrolls, the page does not. A table is the one
 * layout that must not reflow (dropping columns drops data), so the answer to
 * "what happens on a phone" is a scroll container, not a different structure.
 * `contain` stops a sideways swipe at the table edge from paging the browser. */
.table-scroll { overflow-x: auto; overscroll-behavior-x: contain; }
.table-scroll:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

.table { inline-size: 100%; border-collapse: collapse; font-size: var(--font-sm); }
.table[data-size="sm"] { font-size: var(--font-xs); }

.table-th, .table-td {
  text-align: start; padding: var(--space-3) var(--space-4);
  border-block-end: 1px solid var(--border); vertical-align: top;
}
.table[data-size="sm"] .table-th, .table[data-size="sm"] .table-td { padding: var(--space-2) var(--space-3); }

/* A table that bleeds to the card frame still shares the card's left edge: the
 * outer columns take the card padding, so the first column starts under the
 * title rather than 8px to the right of it (owner, 23.08). The rules stay
 * full-bleed — that is what `flush` was for. */
.card[data-flush] .table-th:first-child,
.card[data-flush] .table-td:first-child { padding-inline-start: var(--card-padding); }
.card[data-flush] .table-th:last-child,
.card[data-flush] .table-td:last-child { padding-inline-end: var(--card-padding); }
/* THE TABLE MEETS THE CARD, WITH NO STRIP UNDER IT.
 *
 * Two answers were wrong before this one. `padding-block-end` on the final
 * row's cells made that row 24px taller than the others with its text still at
 * the top, and the hover tint ran down through the empty part. Moving the room
 * onto the table box fixed the row and left a band of card under the last rule,
 * which reads as an unfinished table and cuts a highlighted column short
 * (owner, 23.08, both times). A flush card exists so the rules can reach the
 * frame: the answer is no room at all. */

.table-head .table-th {
  /* The card surface, not `--muted`: a table lives inside a card, and a header
   * painted in the PAGE colour read as a hole cut through it — worst at the top
   * of a flush card, where the muted band sat flush against the muted page.
   * The border and the label typography carry the head/body distinction. */
  background: var(--card); color: var(--muted-foreground);
  font-size: var(--font-xs); font-weight: var(--font-weight-semibold);
  text-transform: uppercase; letter-spacing: var(--tracking-wide); white-space: nowrap;
}
.table[data-sticky] .table-head .table-th {
  position: sticky;
  inset-block-start: 0;
  z-index: var(--z-sticky);
  /* With `border-collapse: collapse` the collapsed border stays with the ROW
   * while the sticky cell travels, so a scrolled header arrived with no line
   * under it and melted into the first row. An inset shadow is painted by the
   * cell itself and travels with it. */
  box-shadow: inset 0 -1px 0 var(--border);
}

/* The data-table variant: one record per LINE. A value never wraps (block
 * elements inside a cell still stack — a two-line identity cell is fine, a
 * phone number broken in half is not) and rows centre their content. */
.table[data-nowrap] .table-th,
.table[data-nowrap] .table-td { white-space: nowrap; vertical-align: middle; }

/* THE LAST ROW OWES NO LINE, AND THE ROW HEADER IS PART OF THE LAST ROW.
 * This zeroed `.table-td` only, so the identifier cell (a <th scope="row">)
 * still drew its border and the last rule ran the width of one column and
 * stopped (owner, 23.08: the bottom row's border does not go all the way). */
/* IN THE BODY. The header row is a <Tr> too, and in a one-row <THead> it is
 * also :last-child — so this rule was silently taking the line out from under
 * every column header in the system, and only a table with a group row above
 * its headers (two header rows) still had one. Measured on the live page, not
 * guessed: computed border-bottom was 0px on twenty of twenty-one headers
 * (owner, 23.08: why do the table headers have no bottom border). */
tbody .table-row:last-child .table-td,
tbody .table-row:last-child .table-th { border-block-end: 0; }
/* Unless something follows it: a detail row, a group heading or a footer are
 * the next block, and the line between them is what says so. */
tbody .table-row:last-child:has(+ .table-detail) .table-td,
tbody .table-row:last-child:has(+ .table-detail) .table-th { border-block-end: 1px solid var(--border); }
/* THE ROW'S STATE IS PAINTED ON THE ROW, NOT ON ITS CELLS.
 *
 * It used to be `.table-row:hover .table-td`, which outranks
 * `.table-td[data-tone]` and `[data-heat]` by one class: hovering a row wiped
 * out every semantic fill and every heatmap step in it, so a pointer moving
 * down a table erased the information the table was painted with (owner,
 * 23.08: the behaviour overrides the coloured cells). Painting the ROW instead
 * fixes it by construction rather than by a longer selector: a cell with a fill
 * of its own paints over the row, a cell without one lets the row show through,
 * and nothing has to know about anything else. */
.table-row:hover { background: var(--surface-hover); }
.table-row[data-selected] { background: var(--accent-soft); }

/* Sortable header: a full-width button so the whole cell is the hit target. The
 * sort arrow is faint until this column is the active sort. */
.table-sort {
  /* 24px floor: with padding 0 this button was as tall as its line of text
   * (19.5px), under SC 2.5.8, and column headers sit shoulder to shoulder. */
  min-block-size: var(--space-6);
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  text-transform: inherit;
  letter-spacing: inherit;
  cursor: pointer;
}
.table-sort:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}
.table-sort-icon { opacity: 0; transition: opacity var(--duration-fast); }
.table-sort:hover .table-sort-icon { opacity: 0.4; }
.table-sort[data-active] .table-sort-icon { opacity: 1; color: var(--primary-accent); }

.table-th[data-align="end"], .table-td[data-align="end"] { text-align: end; font-variant-numeric: tabular-nums; }
.table-th[data-align="center"], .table-td[data-align="center"] { text-align: center; }

/* The same rule as the comparison table's tinted column: a hairline mixed for
 * the card is invisible on a filled cell, so a filled cell mixes its own. */
.table-td[data-tone="success"] { border-block-end-color: color-mix(in oklch, var(--success-soft), var(--foreground) 16%); }
.table-td[data-tone="warning"] { border-block-end-color: color-mix(in oklch, var(--warning-soft), var(--foreground) 16%); }
.table-td[data-tone="danger"] { border-block-end-color: color-mix(in oklch, var(--destructive-soft), var(--foreground) 16%); }
.table-td[data-heat="1"], .table-td[data-heat="2"], .table-td[data-heat="3"], .table-td[data-heat="4"] {
  border-block-end-color: color-mix(in oklch, var(--primary) 55%, var(--card));
}

.table-td[data-emphasis] { font-weight: var(--font-weight-semibold); color: var(--foreground); }
.table-td[data-tone="success"] { background: var(--success-soft); color: var(--success-soft-foreground); }
.table-td[data-tone="warning"] { background: var(--warning-soft); color: var(--warning-soft-foreground); }
.table-td[data-tone="danger"] { background: var(--destructive-soft); color: var(--destructive-soft-foreground); }

/* A row header (scope="row") is a body cell that happens to be a <th>: the
 * column-label treatment (uppercase, muted, no wrap) belongs to the head only. */
tbody .table-th {
  background: transparent;
  color: var(--foreground);
  font-size: inherit;
  font-weight: var(--font-weight-regular);
  text-transform: none;
  letter-spacing: normal;
  white-space: normal;
}
tbody .table-th[data-emphasis] { font-weight: var(--font-weight-semibold); }

/* THE TABLE'S NAME. A caption is the only name that travels with the table
 * itself: an aria-label on the scroll region names the region, and a heading
 * above names the section. [data-hidden] keeps the name for a screen reader
 * when the visible heading already says the same words. */
.table-caption {
  caption-side: top;
  text-align: start;
  padding: var(--space-2) 0 var(--space-3);
  font-size: var(--font-sm);
  color: var(--muted-foreground);
}
/* Hidden the same way `.sr-only` is, and pinned for the same reason: left at
 * its static position deep inside a scrolling pane, a 1px caption stretches the
 * document past the shell and leaves a strip of body colour under the page
 * (measured 2026-08-24: 82px, after the same fault in .sr-only was fixed). */
.table-caption[data-hidden] {
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  inline-size: 1px; block-size: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip-path: inset(50%); white-space: nowrap;
}

/* The row under the rows. A double line, because the total is not one more
 * record: it is what the records add up to. */
.table-foot .table-td, .table-foot .table-th {
  border-block-start: 1px solid var(--border);
  border-block-end: 0;
  background: var(--card);
  font-weight: var(--font-weight-semibold);
  color: var(--foreground);
}
.table[data-sticky-foot] .table-foot .table-td,
.table[data-sticky-foot] .table-foot .table-th {
  position: sticky;
  inset-block-end: 0;
  z-index: var(--z-sticky);
  /* Same reason as the sticky header: with collapsed borders the line stays
   * with the row, so the travelling cell paints its own. */
  box-shadow: inset 0 1px 0 var(--border);
}

/* The anchor column. A sideways scroll that takes the identifier with it
 * leaves the reader on an unnamed row, so the first column stays put. */
.table[data-sticky-col] .table-th:first-child,
.table[data-sticky-col] .table-td:first-child {
  position: sticky;
  inset-inline-start: 0;
  background: var(--card);
  /* Under the sticky header (--z-sticky), over the rows it scrolls past. */
  z-index: calc(var(--z-sticky) - 1);
}
/* The corner belongs to both: it outranks the header row and the frozen column. */
.table[data-sticky-col][data-sticky] .table-head .table-th:first-child {
  z-index: calc(var(--z-sticky) + 1);
}
/* The frozen column is opaque by necessity: it covers the columns scrolling
 * under it, so it is the one cell that has to repeat the row's own state. */
.table[data-sticky-col] .table-row:hover .table-td:first-child,
.table[data-sticky-col] .table-row:hover .table-th:first-child { background: var(--surface-hover); }
.table[data-sticky-col] .table-row[data-selected] .table-td:first-child,
.table[data-sticky-col] .table-row[data-selected] .table-th:first-child { background: var(--accent-soft); }

/* The checkbox column is as wide as its control and no wider. */
.table-th[data-select], .table-td[data-select] {
  inline-size: var(--space-8);
  padding-inline-end: 0;
  vertical-align: middle;
}

/* THE GROUP HEADING. The whole heading is the toggle, so the target is the
 * width of the table rather than a 16px chevron, and it carries its own name
 * instead of needing one. */
/* A QUIET BAND ON A CARD, and the three wrong answers it went through.
 * --muted is the PAGE colour, so inside a card it reads as a hole cut through
 * it. --surface-hover is 1.5% off white: a band nobody can see (owner, 23.08:
 * the backgrounds merge). --accent-soft is what a SELECTED row is painted with,
 * so a group heading in it would say "selected". This is the card's own surface
 * pulled a third of the way to its border: visible on white, correct in dark
 * without a second declaration, and it means nothing else in the system. */
.table-group-cell { padding: 0; background: color-mix(in oklch, var(--card), var(--border) 30%); border-block-end: 1px solid var(--border); }
.table-group-toggle {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  inline-size: 100%;
  padding: var(--space-2) var(--space-4);
  border: none;
  background: transparent;
  color: var(--foreground);
  font: inherit;
  font-size: var(--font-sm);
  font-weight: var(--font-weight-semibold);
  text-align: start;
  cursor: pointer;
}
.table-group-toggle:hover { background: color-mix(in oklch, var(--card), var(--border) 55%); }
.table-group-toggle:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: calc(var(--ring-offset) * -1);
}
.table-group-label { flex: 1; }
.table-group-count {
  font-variant-numeric: tabular-nums;
  font-weight: var(--font-weight-regular);
  color: var(--muted-foreground);
}

/* One chevron, two disclosures (the group heading and the row), one rotation. */
.table-chevron { transition: transform var(--duration-fast); }
[aria-expanded="true"] > .table-chevron { transform: rotate(90deg); }
[dir="rtl"] .table-chevron { transform: rotate(180deg); }
[dir="rtl"] [aria-expanded="true"] > .table-chevron { transform: rotate(90deg); }

.table-expand-cell { inline-size: var(--space-8); padding-inline-end: 0; vertical-align: middle; }
.table-expand {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  /* 24px floor, the same one the sort control carries (SC 2.5.8). */
  inline-size: var(--space-6); block-size: var(--space-6);
  padding: 0;
  border: none;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--muted-foreground);
  cursor: pointer;
}
.table-expand:hover { color: var(--foreground); background: var(--surface-hover); }
.table-expand:focus-visible {
  outline: var(--ring-width) solid var(--ring);
  outline-offset: var(--ring-offset);
}

/* The second layer, in the row's own width. It is not a row of data, so it
 * carries the muted surface rather than the card's. */
.table-detail-cell {
  padding: var(--space-4);
  background: color-mix(in oklch, var(--card), var(--border) 30%);
  border-block-end: 1px solid var(--border);
}

/* No rows. The cell spans the table so the message sits under the columns it
 * is about, not squeezed into the first one. */
.table-empty-cell {
  padding: var(--space-6) var(--space-4);
  border-block-end: 0;
  text-align: center;
}

/* THE HEATMAP RAMP. Five steps of one hue: the eye separates five, and a
 * continuous fill invites a colour nobody can read a value off. The mix stops
 * at 42% so the cell stays a surface the body text can be read on in both
 * themes, rather than a block that needs its own ink. */
.table-td[data-heat="0"] { background: var(--card); }
.table-td[data-heat="1"] { background: color-mix(in oklch, var(--primary) 10%, var(--card)); }
.table-td[data-heat="2"] { background: color-mix(in oklch, var(--primary) 21%, var(--card)); }
.table-td[data-heat="3"] { background: color-mix(in oklch, var(--primary) 32%, var(--card)); }
.table-td[data-heat="4"] { background: color-mix(in oklch, var(--primary) 42%, var(--card)); }

/* THE COLUMN LAYER.
 *
 * `fixed` is what makes a declared width real: with the default algorithm the
 * column widens to fit its longest value, so a width is a suggestion and a
 * truncation never happens. */
.table[data-layout="fixed"] { table-layout: fixed; }

/* A group heading: the second axis of a header, over the columns it names. It
 * centres over its span and carries the line that says where the group ends. */
.table-colgroup {
  border-inline-end: 1px solid var(--border);
  padding-block-end: var(--space-2);
}
.table-colgroup:last-child { border-inline-end: 0; }

/* Column priority. A dropped column is a dropped VALUE, so this is the last
 * resort and never the identifier or the actions: the rule is in the prop's
 * own documentation, and the CSS only does what it is told. */
/* --bp-sm and --bp-md; media queries cannot read a custom property, so the
 * numbers are repeated and the linter holds them to the scale. */
@media (max-width: 30rem) {
  .table-th[data-hide-below="sm"], .table-td[data-hide-below="sm"] { display: none; }
}
@media (max-width: 48rem) {
  .table-th[data-hide-below="md"], .table-td[data-hide-below="md"] { display: none; }
}

import "./Table.css";
import type {
  HTMLAttributes,
  ReactNode,
  Ref,
  TableHTMLAttributes,
  TdHTMLAttributes,
  ThHTMLAttributes,
} from "react";
import { cn } from "../lib/cn";
import { Icon } from "../Icon";
import { Skeleton } from "../Skeleton";

type Size = "sm" | "md";
/** How the columns are sized. `auto` (the default) lets the content decide, so
 *  the table re-flows as the data changes. `fixed` honours the widths the
 *  header declares and is what makes a truncation possible at all: with `auto`
 *  the column simply widens to fit the longest value. */
type Layout = "auto" | "fixed";
/** Below which breakpoint a column is dropped. A column may only be dropped
 *  when its value is reachable another way (an expandable row, the record). */
type HideBelow = "sm" | "md";
type Align = "start" | "end" | "center";
type Tone = "success" | "warning" | "danger";
/** The heatmap ramp: 0 coldest, 4 hottest. Five discrete steps, because that
 *  is what an eye separates without a legend in every cell. */
type Heat = 0 | 1 | 2 | 3 | 4;
/** null = sortable but not the active sort column. */
type SortDirection = "asc" | "desc" | null;

/* Named rather than inline so the registry can read it: the generator extracts
 * the literal half of a named-Props intersection, and an inline annotation left
 * Table with an empty props entry — `verify` then rejected `stickyHeader` on a
 * table that really has it. (Wording note: spelling the declaration syntax out
 * in this comment would itself match the extractor's pattern.) */
type Props = TableHTMLAttributes<HTMLTableElement> & {
  /** Header stays while the rows scroll. It sticks to the nearest scrolling
   *  ancestor, so inside `<TableScroll>` give the wrapper a block size. */
  stickyHeader?: boolean
  /** Keeps `<TFoot>` on the bottom edge: a total that scrolls away is a total
   *  nobody reads. */
  stickyFooter?: boolean
  /** Freezes the first column: when the identifier scrolls out of view the
   *  reader is on an unnamed row. */
  stickyColumn?: boolean
  /** Row density: md (default) / sm for dense reference tables. */
  size?: Size
  /** One record per line: values never wrap mid-value (a phone number broken
   *  in half reads as two numbers) and rows keep one height. It claims width,
   *  so pair it with `<TableScroll>`. */
  nowrap?: boolean
  /** The table's name, as a real `<caption>`. Give it this or an `aria-label`:
   *  a table with neither is unnamed to anyone who cannot see the heading. */
  caption?: ReactNode
  /** Keeps the caption for assistive technology only, when the heading above
   *  already says the same words. */
  captionHidden?: boolean
  /** Column sizing: content-driven (default) or the widths the header declares. */
  layout?: Layout
}

/** A styled, accessible table. Compose inside <Card flush> for an edge-to-edge
 *  surface. Sub-parts: THead, TBody, TFoot, Tr, Th, Td, TrGroup, TrDetail,
 *  TableEmpty, TableSkeleton. 
 *
 * Copy: the caption names what the table lists, even when hidden — it is the
 * table's only name for a screen reader.
 */
export function Table({
  stickyHeader, stickyFooter, stickyColumn, size, nowrap, caption, captionHidden, layout, className, children, ...rest
}: Props) {
  return (
    <table
      className={cn("table", className)}
      data-sticky={stickyHeader || undefined}
      data-sticky-foot={stickyFooter || undefined}
      data-sticky-col={stickyColumn || undefined}
      data-size={size}
      data-nowrap={nowrap || undefined}
      data-layout={layout}
      {...rest}
    >
      {caption ? <caption className="table-caption" data-hidden={captionHidden || undefined}>{caption}</caption> : null}
      {children}
    </table>
  );
}

/** Horizontal scroll container for a table whose columns will not fit. A table
 *  must not reflow (dropping columns drops data), so the row scrolls sideways
 *  and the page does not. `label` names the keyboard tab stop that creates.
 *
 *  Sticky headers stick to the nearest scrolling ancestor, so inside this
 *  wrapper `stickyHeader` needs a block size on the wrapper (via className). */
export function TableScroll({ label, className, ...rest }: HTMLAttributes<HTMLDivElement> & { label: string }) {
  return <div className={cn("table-scroll", className)} role="region" aria-label={label} tabIndex={0} {...rest} />;
}

export function THead(props: HTMLAttributes<HTMLTableSectionElement>) {
  return <thead className="table-head" {...props} />;
}

/** `ref` is forwarded so a composition can own the keyboard for the whole body
 *  (a treegrid walks its rows from one handler). */
export function TBody({ ref, ...rest }: HTMLAttributes<HTMLTableSectionElement> & { ref?: Ref<HTMLTableSectionElement> }) {
  return <tbody ref={ref} {...rest} />;
}

/** Totals and subtotals, in a real `<tfoot>`: not one more record to a screen
 *  reader, and pinned by `<Table stickyFooter>`. */
export function TFoot(props: HTMLAttributes<HTMLTableSectionElement>) {
  return <tfoot className="table-foot" {...props} />;
}

/** `selected` marks a row picked in a selectable table (checkbox column). */
export function Tr({ selected, className, ...rest }: HTMLAttributes<HTMLTableRowElement> & { selected?: boolean }) {
  return <tr className={cn("table-row", className)} data-selected={selected || undefined} aria-selected={selected || undefined} {...rest} />;
}

/* `align` is omitted from the HTML attributes on purpose: the deprecated DOM
 * attribute types it as "left" | "center" | "right" | …, and intersecting that
 * with our logical Align left only "center" assignable, so align="end" did not
 * typecheck even though the CSS styles it. */
export function Th({
  align, sortable, sortDirection, onSort, select, emphasis, width, hideBelow, scope = "col", className, children, style, ...rest
}: Omit<ThHTMLAttributes<HTMLTableCellElement>, "align"> & {
  align?: Align;
  /** Renders the header as a sort control. */
  sortable?: boolean;
  /** Current sort on THIS column: 'asc' / 'desc' / null (sortable but inactive). */
  sortDirection?: SortDirection;
  /** Called when the header is activated to change the sort. */
  onSort?: () => void;
  /** The checkbox column: sized to its control instead of sharing the width. */
  select?: boolean;
  /** A row header's identifier: the record's name, in the body's ink. */
  emphasis?: boolean;
  /** The column's width, declared once on its header. Any CSS length, honoured
   *  under `<Table layout="fixed">`. Fix the predictable columns (status, date,
   *  actions) and let the text ones take what is left. */
  width?: string;
  /** Drops this column below a breakpoint. Only for a column whose value is
   *  reachable another way: dropping a column drops data, and the identifier
   *  and the actions are never the ones to go. */
  hideBelow?: HideBelow;
}) {
  /* `scope` defaults to the column, which is what a header in <THead> is. A row
   * header (the identifier cell of a record) passes scope="row" and is the only
   * way a non-visual reader hears which row a value belongs to. */
  if (!sortable) {
    return (
      <th
        className={cn("table-th", className)}
        data-align={align}
        data-select={select || undefined}
        data-emphasis={emphasis || undefined}
        data-hide-below={hideBelow}
        scope={scope}
        /* A width is a measurement the caller supplies, which is the one thing
         * an inline style is for. */
        style={width ? { ...style, inlineSize: width } : style}
        {...rest}
      >
        {children}
      </th>
    );
  }
  const ariaSort = sortDirection === "asc" ? "ascending" : sortDirection === "desc" ? "descending" : "none";
  /* Inactive columns show the down arrow at low opacity (a "click to sort" hint,
   * styled in CSS); the active column shows the real direction. */
  const sortIcon = sortDirection === "asc" ? "arrow_upward" : "arrow_downward";
  return (
    <th
      className={cn("table-th", className)}
      data-align={align}
      data-hide-below={hideBelow}
      scope={scope}
      aria-sort={ariaSort}
      style={width ? { ...style, inlineSize: width } : style}
      {...rest}
    >
      <button type="button" className="table-sort" data-active={sortDirection ? true : undefined} onClick={onSort}>
        {children}
        <Icon name={sortIcon} className="table-sort-icon" />
      </button>
    </th>
  );
}

export function Td({ align, emphasis, tone, heat, select, hideBelow, className, ...rest }: Omit<TdHTMLAttributes<HTMLTableCellElement>, "align"> & {
  align?: Align;
  emphasis?: boolean;
  tone?: Tone;
  /** Paints the cell on the heatmap ramp (0 to 4), for a table read as a
   *  pattern. `tone` is the semantic fill and says good or bad. */
  heat?: Heat;
  /** The checkbox column: sized to its control instead of sharing the width. */
  select?: boolean;
  /** Drops this cell below a breakpoint. It has to match its header's
   *  `hideBelow`, or the row and the head stop having the same columns. */
  hideBelow?: HideBelow;
}) {
  return (
    <td
      className={cn("table-td", className)}
      data-align={align}
      data-emphasis={emphasis || undefined}
      data-tone={tone}
      data-heat={heat}
      data-select={select || undefined}
      data-hide-below={hideBelow}
      {...rest}
    />
  );
}

/** The heading over a group of COLUMNS: "Q1" over three months, a plan over its
 *  price and its seats. It sits in its own row above the column headers, spans
 *  the columns it names, and is scoped to them so a screen reader can say which
 *  group a value belongs to. A group that exists to tidy the header is
 *  decoration, and decoration in a header costs a row on every screen. */
export function ThGroup({ colSpan, align = "center", className, children, ...rest }: Omit<ThHTMLAttributes<HTMLTableCellElement>, "align"> & {
  colSpan: number;
  align?: Align;
}) {
  return (
    <th className={cn("table-th", "table-colgroup", className)} scope="colgroup" colSpan={colSpan} data-align={align} {...rest}>
      {children}
    </th>
  );
}

/** The heading over a group of rows: its name, its count and the control that
 *  collapses it. A set the READER changes is a filter, not a group. */
export function TrGroup({ label, count, expanded, onToggle, colSpan, className, ...rest }: Omit<HTMLAttributes<HTMLTableRowElement>, "onToggle"> & {
  label: ReactNode;
  /** How many rows are inside, so a collapsed group says what it hides. */
  count?: number;
  expanded: boolean;
  onToggle: () => void;
  /** How many columns the table has, so the heading spans all of them. */
  colSpan: number;
}) {
  return (
    <tr className={cn("table-group", className)} {...rest}>
      {/* colgroup scope: the cell heads every column of the rows under it. The
        * whole heading is the control, so it is not an icon-only target and it
        * reads its own name out. */}
      <th className="table-group-cell" scope="colgroup" colSpan={colSpan}>
        <button type="button" className="table-group-toggle" aria-expanded={expanded} onClick={onToggle}>
          <Icon name="chevron_right" className="table-chevron" />
          <span className="table-group-label">{label}</span>
          {count === undefined ? null : <span className="table-group-count">{count}</span>}
        </button>
      </th>
    </tr>
  );
}

/** The disclosure cell of an expandable row. `label` names WHICH row it
 *  opens: twenty rows of "Expand" name nothing. */
export function TdExpand({ expanded, onToggle, label, className, ...rest }: Omit<TdHTMLAttributes<HTMLTableCellElement>, "onToggle"> & {
  expanded: boolean;
  onToggle: () => void;
  label: string;
}) {
  return (
    <td className={cn("table-td", "table-expand-cell", className)} {...rest}>
      <button type="button" className="table-expand" aria-expanded={expanded} aria-label={label} onClick={onToggle}>
        <Icon name="chevron_right" className="table-chevron" />
      </button>
    </td>
  );
}

/** A row's second layer, in place: render it after its own row, while that row
 *  is expanded, spanning every column. */
export function TrDetail({ colSpan, className, children, ...rest }: HTMLAttributes<HTMLTableRowElement> & { colSpan: number }) {
  return (
    <tr className={cn("table-detail", className)} {...rest}>
      <td className="table-detail-cell" colSpan={colSpan}>{children}</td>
    </tr>
  );
}

/** What the table shows instead of rows. Nothing-yet and nothing-matches are
 *  two different screens: pass the `<EmptyState>` that fits. */
export function TableEmpty({ colSpan, className, children, ...rest }: HTMLAttributes<HTMLTableRowElement> & { colSpan: number }) {
  return (
    <tr className={cn("table-empty", className)} {...rest}>
      <td className="table-empty-cell" colSpan={colSpan}>{children}</td>
    </tr>
  );
}

/** The rows before they arrive, so the layout does not jump. Announce loading
 *  once on the region (aria-busy), not on every shimmer. */
export function TableSkeleton({ columns, rows = 5 }: { columns: number; rows?: number }) {
  return (
    <TBody aria-hidden="true">
      {Array.from({ length: rows }, (_, r) => (
        <Tr key={r}>
          {Array.from({ length: columns }, (_, c) => (
            <Td key={c}><Skeleton shape="text" /></Td>
          ))}
        </Tr>
      ))}
    </TBody>
  );
}
